import { test, expect } from '@playwright/test';

test.describe('Payment Card Decline Error Handling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/payment');
  });

  test('should display error message when payment card is declined', async ({ page }) => {
    await page.fill('input[name="cardNumber"]', '4000 0000 0000 0002'); // Example declined card number
    await page.fill('input[name="expiryDate"]', '12/25');
    await page.fill('input[name="cvv"]', '123');
    await page.click('button[type="submit"]');

    const errorMessage = await page.getByRole('alert');
    await expect(errorMessage).toHaveText('Your payment was declined. Please check your card details or use a different card.');
  });

  test('should not display error message for successful payment', async ({ page }) => {
    await page.fill('input[name="cardNumber"]', '4111 1111 1111 1111'); // Example valid card number
    await page.fill('input[name="expiryDate"]', '12/25');
    await page.fill('input[name="cvv"]', '123');
    await page.click('button[type="submit"]');

    const successMessage = await page.getByText('Payment successful!');
    await expect(successMessage).toBeVisible();
    const errorMessage = await page.getByRole('alert');
    await expect(errorMessage).not.toBeVisible();
  });
});
